<?php
namespace App\Http\Controllers\Tenant;use App\Domain\AI\Knowledge\Models\{KnowledgeSource,KnowledgeSourceVersion};use App\Domain\AI\Knowledge\Services\RequestKnowledgeIndexingService;use App\Http\Controllers\Controller;use App\Http\Requests\Tenant\RequestKnowledgeIndexingRequest;use App\Http\Support\AiLaunchpadHttpGate;use Illuminate\Validation\ValidationException;
final class AiKnowledgeIndexController extends Controller{public function store(RequestKnowledgeIndexingRequest$r,KnowledgeSource$knowledgeSource,KnowledgeSourceVersion$knowledgeVersion,AiLaunchpadHttpGate$gate,RequestKnowledgeIndexingService$service){$gate->ensure($r->user());$gate->assertCurrentTenant($knowledgeSource);$gate->assertCurrentTenant($knowledgeVersion);abort_unless((int)$knowledgeVersion->knowledge_source_id===(int)$knowledgeSource->id,404);try{$service->request($r->user(),$knowledgeSource,$knowledgeVersion);}catch(\DomainException){throw ValidationException::withMessages(['index'=>'Esta versión no puede prepararse.']);}return back()->with('success','La preparación de conocimiento fue solicitada.');}}
